"use client";

import { useState, useEffect, Suspense } from "react";
import { useSearchParams } from "next/navigation";
import { Search, Clock, CheckCircle2, MapPin, Phone, Calendar, ArrowRight, ShieldCheck, RefreshCw } from "lucide-react";
import { Button } from "@/components/ui/button";

interface BookingRecord {
  id: string;
  booking_number: string;
  service_id: string;
  status: 'draft' | 'pending' | 'confirmed' | 'assigned' | 'in_progress' | 'completed' | 'cancelled';
  customer_name: string;
  customer_phone: string;
  customer_address: string;
  preferred_date: string;
  preferred_time: string;
  base_price: number;
  addons_total: number;
  total_price: number;
  created_at: string;
}

function TrackContent() {
  const searchParams = useSearchParams();
  const initialRef = searchParams.get("ref") || "";

  const [query, setQuery] = useState(initialRef);
  const [loading, setLoading] = useState(false);
  const [searched, setSearched] = useState(false);
  const [results, setResults] = useState<BookingRecord[]>([]);
  const [errorMsg, setErrorMsg] = useState("");

  useEffect(() => {
    if (initialRef) {
      handleSearch(initialRef);
    }
  }, [initialRef]);

  const handleSearch = async (searchQuery?: string) => {
    const q = (searchQuery || query).trim();
    if (!q) return;

    setLoading(true);
    setErrorMsg("");
    setSearched(true);

    try {
      const res = await fetch(`/api/bookings/search/${encodeURIComponent(q)}`);
      const data = await res.json();

      if (data.success && data.data) {
        setResults(data.data);
      } else {
        setResults([]);
        setErrorMsg(data.error || "No booking found matching that reference or phone number.");
      }
    } catch (e: any) {
      setErrorMsg("Failed to search booking. Please check your network connection.");
    } finally {
      setLoading(false);
    }
  };

  const getStatusStep = (status: BookingRecord['status']) => {
    switch (status) {
      case 'pending': return 1;
      case 'confirmed': return 2;
      case 'assigned': return 3;
      case 'in_progress': return 4;
      case 'completed': return 5;
      case 'cancelled': return -1;
      default: return 1;
    }
  };

  return (
    <div className="min-h-screen bg-background pb-24 md:pb-16 pt-8">
      <div className="container mx-auto px-4 max-w-2xl">
        
        {/* Header */}
        <div className="text-center mb-8">
          <div className="inline-flex items-center space-x-2 bg-primary/10 text-primary px-3 py-1 rounded-full text-xs font-bold mb-3">
            <Search className="w-3.5 h-3.5" />
            <span>REAL-TIME TRACKING</span>
          </div>
          <h1 className="text-2xl md:text-3xl font-extrabold text-foreground mb-2">Track Service Booking</h1>
          <p className="text-sm text-muted">Enter your booking reference (e.g. ZLV-2026-1042) or mobile number</p>
        </div>

        {/* Search Bar */}
        <div className="bg-white p-2 sm:p-3 rounded-2xl border border-border shadow-md flex items-center space-x-2 mb-8">
          <Search className="w-5 h-5 text-muted ml-2 flex-shrink-0" />
          <input
            type="text"
            placeholder="Enter Booking Ref or Phone No..."
            value={query}
            onChange={(e) => setQuery(e.target.value)}
            onKeyDown={(e) => e.key === "Enter" && handleSearch()}
            className="w-full text-sm font-semibold text-foreground placeholder:text-muted outline-none bg-transparent"
          />
          <Button
            onClick={() => handleSearch()}
            disabled={loading}
            className="bg-primary hover:bg-primaryHover text-white font-bold text-xs px-5 py-2.5 rounded-xl transition-all"
          >
            {loading ? <RefreshCw className="w-4 h-4 animate-spin" /> : "Track"}
          </Button>
        </div>

        {/* Results Section */}
        {searched && (
          <div className="space-y-6">
            {results.length > 0 ? (
              results.map((booking) => {
                const currentStep = getStatusStep(booking.status);

                return (
                  <div key={booking.id} className="bg-white rounded-2xl border border-border/70 p-5 shadow-lg space-y-5">
                    
                    {/* Booking Header */}
                    <div className="flex items-center justify-between border-b border-border/50 pb-4">
                      <div>
                        <span className="text-[10px] text-muted uppercase font-bold tracking-wider">Booking Number</span>
                        <h2 className="text-xl font-black text-primary font-mono">{booking.booking_number}</h2>
                      </div>
                      <span className={`text-xs px-3 py-1 rounded-full font-bold uppercase ${
                        booking.status === 'completed' ? 'bg-emerald-100 text-emerald-700 border border-emerald-300' :
                        booking.status === 'cancelled' ? 'bg-red-100 text-red-700 border border-red-300' :
                        'bg-amber-100 text-amber-800 border border-amber-300'
                      }`}>
                        {booking.status.replace("_", " ")}
                      </span>
                    </div>

                    {/* Progress Timeline Tracker */}
                    {booking.status !== 'cancelled' ? (
                      <div className="py-2">
                        <label className="text-xs font-bold text-foreground block mb-3">Service Progress:</label>
                        <div className="grid grid-cols-5 gap-1 text-center relative">
                          {/* Track bar line */}
                          <div className="absolute top-3.5 left-[10%] right-[10%] h-1 bg-secondaryBg -z-0">
                            <div 
                              className="h-full bg-primary transition-all duration-500" 
                              style={{ width: `${Math.max(0, (currentStep - 1) * 25)}%` }}
                            />
                          </div>

                          {[
                            { step: 1, label: "Pending" },
                            { step: 2, label: "Confirmed" },
                            { step: 3, label: "Assigned" },
                            { step: 4, label: "In Progress" },
                            { step: 5, label: "Completed" }
                          ].map((s) => (
                            <div key={s.step} className="flex flex-col items-center z-10">
                              <div className={`w-7 h-7 rounded-full flex items-center justify-center text-xs font-bold transition-all ${
                                currentStep >= s.step 
                                  ? "bg-primary text-white shadow-sm ring-4 ring-primary/20" 
                                  : "bg-white border-2 border-border text-muted"
                              }`}>
                                {currentStep > s.step ? <CheckCircle2 className="w-4 h-4" /> : s.step}
                              </div>
                              <span className={`text-[10px] mt-1.5 font-semibold ${
                                currentStep >= s.step ? "text-foreground font-bold" : "text-muted"
                              }`}>
                                {s.label}
                              </span>
                            </div>
                          ))}
                        </div>
                      </div>
                    ) : (
                      <div className="bg-red-50 p-3 rounded-xl border border-red-200 text-xs text-red-700 text-center font-medium">
                        This booking has been cancelled. Please contact support for re-booking options.
                      </div>
                    )}

                    {/* Details Grid */}
                    <div className="bg-secondaryBg/40 rounded-xl p-4 grid grid-cols-1 sm:grid-cols-2 gap-3 text-xs">
                      <div className="flex items-start space-x-2">
                        <Calendar className="w-4 h-4 text-primary mt-0.5" />
                        <div>
                          <span className="text-muted block">Scheduled Date:</span>
                          <span className="font-bold text-foreground">{booking.preferred_date}</span>
                        </div>
                      </div>

                      <div className="flex items-start space-x-2">
                        <Clock className="w-4 h-4 text-primary mt-0.5" />
                        <div>
                          <span className="text-muted block">Arrival Window:</span>
                          <span className="font-bold text-foreground">{booking.preferred_time}</span>
                        </div>
                      </div>

                      <div className="flex items-start space-x-2 sm:col-span-2">
                        <MapPin className="w-4 h-4 text-primary mt-0.5" />
                        <div>
                          <span className="text-muted block">Service Address:</span>
                          <span className="font-semibold text-foreground">{booking.customer_address}</span>
                        </div>
                      </div>

                      <div className="flex items-start space-x-2">
                        <Phone className="w-4 h-4 text-primary mt-0.5" />
                        <div>
                          <span className="text-muted block">Contact Phone:</span>
                          <span className="font-bold text-foreground">{booking.customer_phone}</span>
                        </div>
                      </div>

                      <div className="flex items-start space-x-2">
                        <ShieldCheck className="w-4 h-4 text-primary mt-0.5" />
                        <div>
                          <span className="text-muted block">Total Price:</span>
                          <span className="font-extrabold text-primary text-base">₹{booking.total_price.toLocaleString()}</span>
                        </div>
                      </div>
                    </div>

                    {/* Action Support CTA */}
                    <div className="flex items-center justify-between pt-2">
                      <span className="text-xs text-muted">Need help with your booking?</span>
                      <a href="tel:+919876543210" className="text-xs font-bold text-primary flex items-center hover:underline">
                        Call Support <ArrowRight className="w-3.5 h-3.5 ml-1" />
                      </a>
                    </div>

                  </div>
                );
              })
            ) : (
              <div className="bg-white rounded-2xl border border-border/60 p-8 text-center space-y-3">
                <Search className="w-12 h-12 text-muted/50 mx-auto" />
                <h3 className="text-lg font-bold text-foreground">No Booking Found</h3>
                <p className="text-xs text-muted max-w-sm mx-auto">
                  {errorMsg || "We couldn't find any booking matching your query. Please double check your booking reference code or mobile number."}
                </p>
              </div>
            )}
          </div>
        )}

      </div>
    </div>
  );
}

export default function TrackPage() {
  return (
    <Suspense fallback={
      <div className="min-h-screen bg-background flex items-center justify-center p-4">
        <div className="text-center space-y-2">
          <RefreshCw className="w-8 h-8 animate-spin text-primary mx-auto" />
          <p className="text-sm font-semibold text-muted">Loading tracking portal...</p>
        </div>
      </div>
    }>
      <TrackContent />
    </Suspense>
  );
}
